function changeTitheMonth(delta){
 const [year,monthNumber]=titheViewMonth.split('-').map(Number);
 const next=new Date(year,monthNumber-1+delta,1,12);
 const target=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`;
 if(target>mk(new Date()))return;
 titheViewMonth=target;tithe();
}
