let paymentExpenseId=null;function paymentModal(){let el=$('paymentActionModal');if(!el){el=document.createElement('div');el.id='paymentActionModal';el.className='modal hidden';el.innerHTML='<div class="modal-card"><div class="modal-head"><h2>Registrar pagamento</h2><button type="button" class="icon-btn" data-payment-close>×</button></div><p id="paymentDescription" class="muted"></p><label class="payment-amount-field">Valor do pagamento parcial<input id="paymentAmount" inputmode="decimal" placeholder="Ex.: 50,00"></label><div class="actions"><button type="button" class="primary-btn" id="payInFull">Quitar despesa</button><button type="button" class="secondary-btn" id="payPart">Registrar pagamento parcial</button></div><button type="button" class="text-btn" data-payment-close>Cancelar</button></div>';document.body.appendChild(el);el.addEventListener('click',ev=>{if(ev.target===el||ev.target.closest('[data-payment-close]'))el.classList.add('hidden')});$('payInFull').onclick=()=>applyPayment(true);$('payPart').onclick=()=>applyPayment(false)}return el}function openPayment(id){const e=st.expenses.find(x=>x.id===id);if(!e)return;const modal=paymentModal();paymentExpenseId=id;$('paymentDescription').textContent=e.description+' · Em aberto: '+money(remaining(e));$('paymentAmount').value='';modal.classList.remove('hidden')}function applyPayment(full){const e=st.expenses.find(x=>x.id===paymentExpenseId);if(!e)return;const open=remaining(e);let amount;if(full){if(!confirm('Confirmar a quitação total desta despesa?'))return;amount=open}else{amount=pm($('paymentAmount').value);if(amount<=0||amount>open){alert('Informe um valor maior que zero e até '+money(open)+'.');return}}e.paidAmount=(+e.paidAmount||0)+amount;e.partialPayments=Array.isArray(e.partialPayments)?e.partialPayments:[];e.partialPayments.push({amount,date:iso(new Date())});e.status=remaining(e)<=0.005?'pago':'parcial';if(e.status==='pago')e.paidDate=iso(new Date());save();$('paymentActionModal').classList.add('hidden');paymentExpenseId=null;render()}$('calendarPrevMonth').onclick=()=>{calendarView.month=iso(add(calendarView.month+'-01',-1,1)).slice(0,7);calendar()};$('calendarNextMonth').onclick=()=>{calendarView.month=iso(add(calendarView.month+'-01',1,1)).slice(0,7);calendar()};document.addEventListener('click',e=>{const day=e.target.closest('[data-calendar-day]');if(day){calendarView.selected=day.dataset.calendarDay;calendar();return}const action=e.target.closest('[data-calendar-action]');if(action){if(action.dataset.calendarAction==='invoice'){st.activeCard=action.dataset.calendarCard;st.activeInvoice=mk(calendarView.selected);page('cardDetail')}else{const item=st.expenses.find(x=>x.id===action.dataset.calendarId);if(item){if(remaining(item)<=0.005)openExpense(item);else openPayment(item.id)}}}});function openDeleteExpense(id){const target=st.expenses.find(item=>item.id===id);if(!target)return;if(confirm('Excluir esta despesa?')){st.expenses=st.expenses.filter(item=>item.id!==id);save();render()}}
document.addEventListener('click',e=>{const categoryButton=e.target.closest('[data-category-drill]');if(categoryButton){openCategoryDetail(categoryButton.dataset.categoryDrill,categoryButton.dataset.categoryType);return}let p=e.target.closest('[data-page]')?.dataset.page;if(p)return page(p);let b=e.target.closest('[data-a]');if(!b)return;let a=b.dataset.a,id=b.dataset.id;if(a==='pay'){let x=st.expenses.find(e=>e.id===id);if(!x)return;if(x.status==='pago'||remaining(x)<=0.005){if(!confirm('Reabrir esta despesa?'))return;x.paidAmount=0;x.status='pendente';x.paidDate=null;x.partialPayments=[];save();render()}else openPayment(id);return}if(a==='del'){openDeleteExpense(id);return}if(a==='edit')openExpense(st.expenses.find(e=>e.id===id));if(a==='invoice'){st.activeCard=b.dataset.card;st.activeInvoice=st.cardsMonth;page('cardDetail')}if(a==='carddel'){if(confirm('Excluir este cartão?')){st.cards=st.cards.filter(c=>c.id!==b.dataset.card);save();cards()}}if(a==='cardedit'){let c=st.cards.find(c=>c.id===b.dataset.card);if(c)openCardEditor(c)}if(b.dataset.cat){if(!confirm('Remover esta categoria das opções de novos lançamentos? Os lançamentos antigos serão preservados.'))return;st.categories=st.categories.filter(c=>c!==b.dataset.cat);if(st.categoryColors)delete st.categoryColors[b.dataset.cat];save();fill();settings();dash();report()}if(b.dataset.catEdit){openCategoryEditor(b.dataset.catEdit)}});$('payInvoice').onclick=()=>{const paidOn=iso(new Date());all().filter(e=>e.cardId===st.activeCard&&mk(e.dueDate||e.date)===st.activeInvoice).forEach(e=>{const open=remaining(e);if(open>0.005){e.paidAmount=(+e.paidAmount||0)+open;e.partialPayments=Array.isArray(e.partialPayments)?e.partialPayments:[];e.partialPayments.push({amount:open,date:paidOn})}e.status='pago';e.paidDate=paidOn});save();invoice()};$('reopenInvoice').onclick=()=>{if(!confirm('Desfazer a quitação desta fatura e zerar os pagamentos registrados nela?'))return;all().filter(e=>e.cardId===st.activeCard&&mk(e.dueDate||e.date)===st.activeInvoice).forEach(e=>{e.paidAmount=0;e.status='pendente';e.paidDate=null;e.partialPayments=[]});save();invoice()};
let dueNoticeReturnFocus=null;
function checkDueTodayNotice(){

 const today=iso(new Date()),seenKey='gf3_due_notice_seen_'+today;
 if(localStorage.getItem(seenKey))return;
 const due=all().filter(e=>String(e.dueDate||e.date)===today&&remaining(e)>0.005);
 const items=[],invoices=new Map();
 due.forEach(e=>{
  if(e.cardId){
   const key=e.cardId+'|'+String(e.dueDate||e.date);
   if(!invoices.has(key))invoices.set(key,{cardId:e.cardId,dueDate:e.dueDate||e.date,amount:0});
   invoices.get(key).amount+=remaining(e);
  }else items.push({label:e.description||'Despesa',amount:remaining(e)});
 });
 invoices.forEach(inv=>{
  const card=st.cards.find(c=>c.id===inv.cardId);
  items.push({label:'Fatura · '+(card?.name||'Cartão de crédito'),amount:inv.amount});
 });
 if(!items.length)return;
 const modal=$('dueTodayNotice'),list=$('dueTodayNoticeList');dueNoticeReturnFocus=document.activeElement;
 $('dueTodayNoticeTitle').textContent=items.length===1?'Você tem 1 conta vencendo hoje':'Você tem '+items.length+' contas vencendo hoje';
 list.innerHTML=items.map(item=>'<div class="due-notice-row"><span>'+esc(item.label)+'</span><strong>'+money(item.amount)+'</strong></div>').join('');
 $('dueTodayNoticeTotal').textContent=money(items.reduce((sum,item)=>sum+item.amount,0));
 modal.classList.remove('hidden');
 $('confirmDueTodayNotice').focus();
 $('confirmDueTodayNotice').onclick=()=>{localStorage.setItem(seenKey,'1');modal.classList.add('hidden');if(dueNoticeReturnFocus?.focus)dueNoticeReturnFocus.focus()};
 modal.onkeydown=e=>{if(e.key==='Tab'){const button=$('confirmDueTodayNotice');e.preventDefault();button.focus()}};

}
window.gf3PersistLocal=()=>{try{const local=JSON.parse(localStorage.getItem(K)||'null');if(local)st=Object.assign(st,local)}catch{}save();return cloudWrite};
window.gf3Refresh=render;
cloudStatus('Conectando...');
onAuthStateChanged(auth,async user=>{
 const generation=++authLoadGeneration,revisionAtLoad=localRevision;
 if(cloudUser&&cloudUser.uid!==(user?.uid||null))syncPending=false;
 cloudReady=false;cloudUser=user||null;syncFailed=false;
 if(retryTimer){clearTimeout(retryTimer);retryTimer=null}
 if(!user){cloudStatus('Aguardando login');return}
 cloudStatus('Carregando seus dados...');
 try{
  const ref=doc(db,'users',user.uid,'data','main');
  const snapshot=await getDoc(ref);
  if(generation!==authLoadGeneration||cloudUser?.uid!==user.uid)return;
  const changedDuringLoad=localRevision!==revisionAtLoad||syncPending;
  if(snapshot.exists()&&!changedDuringLoad){
   const remote=snapshot.data();
   st=Object.assign({expenses:[],cards:[],categories:C.slice(),settings:{tithe:10},month:new Date().toISOString().slice(0,10),expensesMonth:new Date().toISOString().slice(0,7),cardsMonth:new Date().toISOString().slice(0,7)},remote);
   const validMonth=v=>typeof v==='string'&&/^\d{4}-\d{2}$/.test(v)&&Number(v.slice(5,7))>=1&&Number(v.slice(5,7))<=12;
   const fallbackMonth=new Date().toISOString().slice(0,7);
   if(!validMonth(st.expensesMonth))st.expensesMonth=fallbackMonth;
   if(!validMonth(st.cardsMonth))st.cardsMonth=fallbackMonth;
   st.categories=Array.isArray(st.categories)?st.categories:C.slice();
   st.subcategories=st.subcategories&&typeof st.subcategories==='object'?st.subcategories:{};st.categoryTypes=st.categoryTypes&&typeof st.categoryTypes==='object'?st.categoryTypes:{};st.categories.forEach(c=>{if(!['Pessoal','Empresa'].includes(st.categoryTypes[c]))st.categoryTypes[c]='Pessoal'});
   st.categoryColors=st.categoryColors&&typeof st.categoryColors==='object'?st.categoryColors:{};
   localStorage.setItem(K,JSON.stringify(st));
  }else if(!snapshot.exists()&&!changedDuringLoad){
   await setDoc(ref,{...st,updatedAt:serverTimestamp()});
   if(generation!==authLoadGeneration||cloudUser?.uid!==user.uid)return;
   localStorage.setItem(K,JSON.stringify(st));
  }else{
   syncPending=true;
  }
  if(generation!==authLoadGeneration||cloudUser?.uid!==user.uid)return;
  if(applyCategoryCatalog()){localStorage.setItem(K,JSON.stringify(st));syncPending=true;}if(applyExpenseCleanup()){localStorage.setItem(K,JSON.stringify(st));syncPending=true;}
  cloudReady=true;
  if(changedDuringLoad||syncPending){syncPending=true;queueCloudSync()}
  else cloudStatus('Dados sincronizados');
  page('dashboard');checkDueTodayNotice();
 }catch(error){
  if(generation!==authLoadGeneration)return;
  console.error('Erro ao carregar dados do Firestore:',error);
  cloudReady=false;cloudStatus('Erro ao conectar à nuvem');
  alert('Não foi possível carregar seus dados na nuvem. Nenhuma informação local foi apagada. Verifique sua conexão e tente entrar novamente.');
  page('dashboard');
 }
});